/* PRD 4 layer G, the Black Market's rules (the trader and its screen are definitive_market_screen.c).
 *
 * The Exchange turns one rare item (a region's "<species> Core <numeral>", definitive_bestiary.c's second record) into
 * DEF_BM_COMMONS of the common Hunt Material the player picks: the owner's economy, where surplus rares refill the
 * commons the forge asks for in large amounts. It happens only when the whole lot fits under DEF_HUNT_MATERIAL_CAP, so
 * no exchange ever creates or destroys anything outside that rate.
 *
 * The Legendary Replicas (def_replicas, generated by tools/gen_replicas.py: equipment no shop sells) cost
 * DEF_BM_REPLICA_RARES rare items of distinct bosses, the lead species of their Rare Targets (the same species leads
 * several regions: "Datamon IV" and "Datamon VII" are one boss), plus Bits. The screen takes the most plentiful ones,
 * so what goes is the surplus. A replica is the item's own ID, so the card record keeps one bit per replica
 * (REC_EXTRA + 26..27), and while it is set the shops pay 0 for that ID (def_item_sell), an original held besides it
 * included: the PRD's accepted simplification. The bit clears once the player holds none of the ID, in the bag or
 * equipped (def_bm_sweep, every field frame), so a replica sold for nothing and a later original are told apart.
 *
 * Off in a replay script (def_on): nothing changes, every price is the game's. */
#include "common.h"
#include "gamestate.h"

#include "definitive.h"

extern int def_on(void); /* port.h declares it under PC_PORT only; the host test builds without it */
extern void port_log(const char *fmt, ...);

#define ITEM_SLOTS ((int)sizeof(gamestate_data.items)) /* the bag's counters, indexed by item ID */

int def_bm_held(int item) {
    if (item <= 0 || item >= ITEM_SLOTS) {
        return 0;
    }
    return gamestate_data.items[item] + gamestate_data.items_equipped[item];
}

int def_bm_replica_of(int item) {
    int r;

    for (r = 0; r < def_replica_count && r < DEF_REPLICAS; r++) {
        if (def_replicas[r].item == item) {
            return r;
        }
    }
    return -1;
}

int def_bm_resale_zero(int item) {
    int r;

    if (!def_on()) {
        return 0;
    }
    r = def_bm_replica_of(item);
    return r >= 0 && def_record_replica(r);
}

void def_bm_sweep(void) {
    int r;

    if (!def_on()) {
        return;
    }
    for (r = 0; r < def_replica_count && r < DEF_REPLICAS; r++) {
        if (def_record_replica(r) && def_bm_held(def_replicas[r].item) <= 0) {
            def_record_replica_set(r, 0);
            port_log("market: replica %d (item %d) no longer held: its resale is back", r, def_replicas[r].item);
        }
    }
}

/* ---- The Exchange */
int def_bm_exchange_check(int rare, int common) {
    if (!def_on()) {
        return DEF_BM_OFF;
    }
    if (rare < 0 || rare >= def_hunt_target_count || def_record_rare(rare) < 1) {
        return DEF_BM_NO_RARE;
    }
    if (common < 0 || common >= DEF_HUNT_MATERIALS ||
        def_record_material(common) + DEF_BM_COMMONS > DEF_HUNT_MATERIAL_CAP) {
        return DEF_BM_NO_ROOM;
    }
    return DEF_BM_OK;
}

int def_bm_exchange(int rare, int common) {
    int why = def_bm_exchange_check(rare, common);

    if (why != DEF_BM_OK) {
        return why;
    }
    def_record_rare_add(rare, -1);
    def_record_material_add(common, DEF_BM_COMMONS);
    port_log("market: rare %d for common %d x%d (now %d, rare left %d)", rare, common, DEF_BM_COMMONS,
             def_record_material(common), def_record_rare(rare));
    return DEF_BM_OK;
}

/* ---- The Legendary Replicas */
static int picked_lead(const int *picks, int n, int lead) {
    int j;

    for (j = 0; j < n; j++) {
        if (def_hunt_target_lead(picks[j]) == lead) {
            return 1;
        }
    }
    return 0;
}

/* Greedy, one boss at a time: the most plentiful rare of a boss not taken yet; a tie goes to the weaker target (the
 * cheaper one to hunt again), then to the table's order. It finds a set whenever the rares held span enough bosses,
 * since each step only rules out the bosses already taken. */
int def_bm_replica_pick(int picks[DEF_BM_REPLICA_RARES]) {
    int k, t, best, n;

    for (k = 0; k < DEF_BM_REPLICA_RARES; k++) {
        best = -1;
        for (t = 0; t < def_hunt_target_count; t++) {
            n = def_record_rare(t);
            if (n < 1 || picked_lead(picks, k, def_hunt_target_lead(t))) {
                continue;
            }
            if (best < 0 || n > def_record_rare(best) ||
                (n == def_record_rare(best) && def_hunt_targets[t].level < def_hunt_targets[best].level)) {
                best = t;
            }
        }
        if (best < 0) {
            return 0;
        }
        picks[k] = best;
    }
    return 1;
}

int def_bm_replica_check(int r, int picks[DEF_BM_REPLICA_RARES]) {
    if (!def_on()) {
        return DEF_BM_OFF;
    }
    if (r < 0 || r >= def_replica_count || r >= DEF_REPLICAS || !def_bm_replica_pick(picks)) {
        return DEF_BM_NO_BOSSES;
    }
    if (gamestate_data.money < def_replicas[r].bits) {
        return DEF_BM_NO_BITS;
    }
    if (gamestate_data.items[def_replicas[r].item] >= DEF_BM_ITEM_CAP) {
        return DEF_BM_BAG_FULL;
    }
    return DEF_BM_OK;
}

int def_bm_replica_buy(int r) {
    int picks[DEF_BM_REPLICA_RARES], why = def_bm_replica_check(r, picks), k;

    if (why != DEF_BM_OK) {
        return why;
    }
    for (k = 0; k < DEF_BM_REPLICA_RARES; k++) {
        def_record_rare_add(picks[k], -1);
    }
    gamestate_data.money -= def_replicas[r].bits;
    gamestate_data.items[def_replicas[r].item]++;
    def_record_replica_set(r, 1);
    port_log("market: replica %d (item %d) for %d Bits and rares %d, %d", r, def_replicas[r].item, def_replicas[r].bits,
             picks[0], DEF_BM_REPLICA_RARES > 1 ? picks[DEF_BM_REPLICA_RARES - 1] : -1);
    return DEF_BM_OK;
}
